// Ported from the Node app's Sequelize model StockMovement (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class StockMovementConfiguration : IEntityTypeConfiguration<StockMovement>
{
    public void Configure(EntityTypeBuilder<StockMovement> builder)
    {
        builder.ToTable("stock_movements", t =>
        {
            t.HasCheckConstraint("CK_stock_movements_type", "[type] IN (N'in', N'out')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.ItemId).HasColumnName("item_id");
        builder.Property(e => e.Type).HasColumnName("type").HasColumnType("nvarchar(20)").IsRequired();
        builder.Property(e => e.Quantity).HasColumnName("quantity");
        builder.Property(e => e.UnitCost).HasColumnName("unit_cost").HasColumnType("decimal(10,2)");
        builder.Property(e => e.SupplierId).HasColumnName("supplier_id");
        builder.Property(e => e.OrderId).HasColumnName("order_id");
        builder.Property(e => e.Party).HasColumnName("party").HasColumnType("nvarchar(120)").HasMaxLength(120);
        builder.Property(e => e.Note).HasColumnName("note").HasColumnType("nvarchar(255)").HasMaxLength(255);
        builder.Property(e => e.Date).HasColumnName("date").HasColumnType("date");
        builder.Property(e => e.CreatedByName).HasColumnName("created_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.CreatedAt).HasColumnName("created_at").HasColumnType("datetime2");
        builder.HasOne(e => e.InventoryItem).WithMany(p => p.StockMovements).HasForeignKey(e => e.ItemId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Supplier).WithMany(p => p.StockMovements).HasForeignKey(e => e.SupplierId).OnDelete(DeleteBehavior.NoAction);
    }
}
